  1	//! MPSC v3 producing endpoint: [`MpscProducer`] claims a
  2	//! position by CAS on the packed claim word, a closure fills the
  3	//! slot in place, and the commit happens on closure return, as
  4	//! v1's. At a full segment it takes a free one and moves the ring
  5	//! on, sealing the old segment behind it. The handle is one
  6	//! counted producer role, given back by `release`.
  7	
  8	use core::marker::PhantomData;
  9	use core::sync::atomic::{AtomicU32, Ordering};
 10	use zerocopy::{FromBytes, IntoBytes, KnownLayout};
 11	
 12	use super::{
 13	    MOVED, Mode, Multi, Segments, WAITING, check_body_type, seq_of, word, word_pos, word_seg,
 14	};
 15	use crate::Full;
 16	use crate::wake::{NoWake, Wake};
