 18	/// A producing handle, one counted producer role: claim one per
 19	/// producing thread or process with
 20	/// [`MpscRing::claim_producer`](super::MpscRing::claim_producer),
 21	/// then `send_with`.
 22	///
 23	/// - `send_with` takes `&self`: exclusivity comes from the claim
 24	///   CAS, not the borrow, so one handle may also be shared by
 25	///   reference.
 26	/// - Not `Clone`: each handle is one count in the roles word, and
 27	///   [`release`](MpscProducer::release) gives it back. Dropping
 28	///   the handle writes nothing, so the count stays held.
 29	pub struct MpscProducer<'a, M: Mode = Multi, W: Wake = NoWake> {
 30	    /// Geometry and segment addresses.
 31	    pub(super) segs: Segments,
 32	    _region: PhantomData<(&'a [u8], M, W)>,
 33	}
 34	
 35	// SAFETY: any number of producers is the protocol contract: the
 36	// shared state (the header words, the slot seqs) is atomic, slot
 37	// claims are exclusive by CAS, and slot writes are handed off
 38	// with Release/Acquire ordering.
 39	unsafe impl<M: Mode, W: Wake> Send for MpscProducer<'_, M, W> {}
 40	// SAFETY: send_with is &self and every access is protected as
 41	// above, so shared references across threads are equally fine.
 42	unsafe impl<M: Mode, W: Wake> Sync for MpscProducer<'_, M, W> {}
 43	
 44	/// Wake the consumer asleep on the claim word, out of line and
 45	/// cold, so the send loop compiles as it does without a wake.
 46	#[cold]
 47	#[inline(never)]
 48	fn wake_consumer<W: Wake>(claim: &AtomicU32) {
 49	    W::wake(claim);
 50	}
 51	
 52	/// Why a switch attempt did not move the ring.
 53	enum NoSwitch {
 54	    /// No segment is free: the ring is Full.
 55	    NoFree,
 56	    /// The claim word moved under the attempt: another producer
 57	    /// switched, or the slot was released and claimed.
 58	    Lost,
 59	}
 60	
 61	impl<'a, M: Mode, W: Wake> MpscProducer<'a, M, W> {
 62	    /// Build the handle for a claimed role from the ring's
 63	    /// geometry snapshot.
 64	    pub(super) fn new(segs: Segments) -> Self {
 65	        MpscProducer {
 66	            segs,
 67	            _region: PhantomData,
 68	        }
 69	    }
 70	
 71	    /// Give the producer role back, counting it out of the roles
 72	    /// word.
 73	    ///
 74	    /// - The producer keeps no state of its own, so nothing is
 75	    ///   checkpointed: a later claim, in any process, sends on
 76	    ///   where the ring is.
 77	    pub fn release(self) {
 78	        // Release: the ring's release, which needs no role held,
 79	        // sees everything this producer committed.
 80	        self.segs.roles().fetch_sub(1, Ordering::Release);
 81	    }
 82	
 83	    /// Segment switches the ring's producers have made: how many
 84	    /// times a producer at a full segment moved the ring to a
 85	    /// free one. Once the consumer has read everything sent, it
 86	    /// equals the consumer's count.
 87	    pub fn switches(&self) -> u64 {
 88	        self.segs.switches().load(Ordering::Relaxed) as u64
 89	    }
 90	
 91	    /// The segment the ring's producers write into, `0` to the
 92	    /// ring's segment count less one.
 93	    pub fn segment(&self) -> u32 {
 94	        word_seg(self.segs.claim().load(Ordering::Relaxed))
 95	    }
 96	
 97	    /// Claim the next position, fill it in place, commit on
 98	    /// closure return, and retry a full ring under the injected wait
 99	    /// policy, then [`Full`].
100	    ///
101	    /// - `fill` writes the message through `&mut T`, and commit is by
102	    ///   construction, so there is no abandonment state. If `fill`
103	    ///   panics, its slot stays claimed and never committed, as if
104	    ///   the producer had been killed there: the consumer waits at
105	    ///   it, and the ring is recovered by a restart.
106	    /// - `on_full` is called after each failed attempt with the
107	    ///   attempt count (0-based, saturating), and returning `false`
108	    ///   gives up. Pass `|_| false` for a single non-blocking
109	    ///   probe. Full means the current segment's next slot is
110	    ///   unread and no segment is free.
111	    /// - Losing a claim race, or a switch race, is not a policy
112	    ///   call: the ring made progress, and this producer retries
113	    ///   with the fresher claim word.
114	    /// - `T` must fit the slot body, `slot_size` less
115	    ///   [`SLOT_HEADER_BYTES`](super::SLOT_HEADER_BYTES), at an
116	    ///   alignment of at most that.
117	    /// - A consumer asleep on the empty ring is woken after the
118	    ///   commit, when its [`Wake`] wakes.
119	    pub fn send_with<T>(
120	        &self,
121	        on_full: impl FnMut(u32) -> bool,
122	        fill: impl FnOnce(&mut T),
123	    ) -> Result<(), Full>
124	    where
125	        T: FromBytes + IntoBytes + KnownLayout,
126	    {
127	        self.send(on_full, |_| {}, fill, false)
128	    }
129	
130	    /// [`send_with`](MpscProducer::send_with), calling `on_lost`
131	    /// after each claim race this producer loses, with the count of
132	    /// losses in a row, 1 for the first. A weak CAS failing
133	    /// spuriously counts as a loss.
134	    ///
135	    /// - A lost race is no policy call in `send_with`: the ring made
136	    ///   progress, and the loser reads the claim word again at once.
137	    ///   With many producers that read pulls the contended line from
138	    ///   the winner on every loss, so `on_lost` is where a producer
139	    ///   backs off, [`policy::backoff`](crate::policy::backoff) the
140	    ///   model.
141	    pub fn send_with_backoff<T>(
142	        &self,
143	        on_full: impl FnMut(u32) -> bool,
144	        on_lost: impl FnMut(u32),
145	        fill: impl FnOnce(&mut T),
146	    ) -> Result<(), Full>
147	    where
148	        T: FromBytes + IntoBytes + KnownLayout,
149	    {
150	        self.send(on_full, on_lost, fill, false)
151	    }
152	
153	    /// [`send_with`](MpscProducer::send_with), sleeping on a full
154	    /// ring until the consumer frees room, then calling `on_full`
155	    /// after each wake.
156	    ///
157	    /// - The sleep is `W`'s: with [`NoWake`] it is a spin, and with
158	    ///   a futex it returns when the consumer wakes it or at its
159	    ///   timeout, so `on_full` also counts the timeouts, and bounds
160	    ///   the wait as it bounds a spin. Pass `|_| true` to wait until
161	    ///   there is room.
162	    /// - The consumer checks for sleepers every half segment of
163	    ///   releases, not every release, so a sleeping producer is
164	    ///   woken within half a segment of room.
165	    pub fn send_wait<T>(
166	        &self,
167	        on_full: impl FnMut(u32) -> bool,
168	        fill: impl FnOnce(&mut T),
169	    ) -> Result<(), Full>
170	    where
171	        T: FromBytes + IntoBytes + KnownLayout,
172	    {
173	        self.send(on_full, |_| {}, fill, true)
174	    }
175	
176	    /// The send the entries share, calling `on_lost` after each
177	    /// lost claim race and sleeping on a full ring when `sleep` is
178	    /// set.
179	    #[inline(always)]
180	    fn send<T>(
181	        &self,
182	        mut on_full: impl FnMut(u32) -> bool,
183	        mut on_lost: impl FnMut(u32),
184	        fill: impl FnOnce(&mut T),
185	        sleep: bool,
186	    ) -> Result<(), Full>
187	    where
188	        T: FromBytes + IntoBytes + KnownLayout,
189	    {
190	        let segs = &self.segs;
191	        check_body_type::<T>(segs.slot_size);
192	        let claim = segs.claim();
193	        // SeqCst on every claim word access, as v1's index: the
194	        // claim is only exclusive if these are linearizable.
195	        let mut w = claim.load(Ordering::SeqCst);
196	        let mut attempt = 0u32;
197	        let mut lost = 0u32;
198	        let (seg, pos) = loop {
199	            // Single: segment 0 always, whatever the word's segment
200	            // bits hold, so the check below folds away.
201	            let seg = if M::MULTI { word_seg(w) } else { 0 };
202	            let pos = word_pos(w);
203	            if M::MULTI && seg >= segs.seg_count {
204	                // A scribbled claim word: the ring is wedged, and
205	                // this degrades toward Full, never toward a slot
206	                // the ring does not have.
207	                return Err(Full);
208	            }
209	            // Acquire pairs with the consumer's Release in
210	            // release(): a claimable seq means the previous lap's
211	            // reads are done.
212	            let seq = segs.seq(seg, pos).load(Ordering::Acquire);
213	            if seq == pos {
214	                // Claimable. Weak CAS: a spurious failure just
215	                // retries with the fresher word. The consumer's
216	                // waiting flag carries over, cleared only by the
217	                // consumer.
218	                match claim.compare_exchange_weak(
219	                    w,
220	                    word(seg, pos.wrapping_add(1)) | (w & WAITING),
221	                    Ordering::SeqCst,
222	                    Ordering::SeqCst,
223	                ) {
224	                    Ok(_) => break (seg, pos),
225	                    Err(actual) => {
226	                        w = actual;
227	                        lost = lost.saturating_add(1);
228	                        on_lost(lost);
229	                    }
230	                }
231	                continue;
232	            }
233	            // Not claimable at pos: a stale word or a full
234	            // segment, told apart by re-reading, as v1 does.
235	            let cur = claim.load(Ordering::SeqCst);
236	            if cur != w {
237	                w = cur;
238	                continue;
239	            }
240	            // Single has no segment to switch to: the ring is Full.
241	            let switched = if M::MULTI {
242	                self.switch(w)
243	            } else {
244	                Err(NoSwitch::NoFree)
245	            };
246	            match switched {
247	                Ok(()) | Err(NoSwitch::Lost) => {}
248	                Err(NoSwitch::NoFree) => {
249	                    if sleep {
250	                        self.sleep_full();
251	                    }
252	                    if !on_full(attempt) {
253	                        return Err(Full);
254	                    }
255	                    attempt = attempt.saturating_add(1);
256	                }
257	            }
258	            w = claim.load(Ordering::SeqCst);
259	        };
260	        // (seg, pos) is exclusively ours until the seq commit
261	        // store.
262	        let msg = segs.body(seg, pos) as *mut T;
263	        let commit = seq_of(pos.wrapping_add(segs.commit_add));
264	        let seq = segs.seq(seg, pos);
265	        // SAFETY: msg is in-bounds and aligned (check_body_type
266	        // against the body's offset in a line-aligned slot), any
267	        // byte pattern is a valid T (FromBytes bound), and the
268	        // claim CAS gives exclusive slot access until the commit
269	        // store below.
270	        fill(unsafe { &mut *msg });
271	        // Release pairs with the consumer's Acquire seq load:
272	        // observing pos + M + 1 means the filled bytes are
273	        // visible.
274	        seq.store(commit, Ordering::Release);
275	        // The claim CAS returned the word it replaced, flag and
276	        // all, so learning the consumer sleeps costs nothing.
277	        if W::WAKES && w & WAITING != 0 {
278	            wake_consumer::<W>(claim);
279	        }
280	        Ok(())
281	    }
282	
283	    /// Sleep on a full ring until the consumer frees room, a wake
284	    /// that comes early, or `W`'s timeout.
285	    ///
286	    /// - Count in, then look again: the consumer's check fences
287	    ///   its releases before it reads the count, and the fence here
288	    ///   orders the count before the look, so either the consumer
289	    ///   sees this producer or this producer sees the room.
290	    /// - The wake sequence is read before the look, so a wake
291	    ///   between the look and the sleep moves the word and the
292	    ///   sleep returns at once.
293	    #[cold]
294	    #[inline(never)]
295	    fn sleep_full(&self) {
296	        let segs = &self.segs;
297	        let c = segs.claims();
298	        c.prod_waiters.fetch_add(1, Ordering::SeqCst);
299	        core::sync::atomic::fence(Ordering::SeqCst);
300	        let seen = c.prod_wake.load(Ordering::SeqCst);
301	        if !self.has_room() {
302	            W::wait(&c.prod_wake, seen);
303	        }
304	        c.prod_waiters.fetch_sub(1, Ordering::SeqCst);
305	    }
306	
307	    /// Whether a claim could land now: the claim word's slot is
308	    /// claimable, or a `Multi` ring has a free segment.
309	    fn has_room(&self) -> bool {
310	        let segs = &self.segs;
311	        let w = segs.claim().load(Ordering::SeqCst);
312	        let seg = if M::MULTI { word_seg(w) } else { 0 };
313	        if seg >= segs.seg_count {
314	            return true;
315	        }
316	        let pos = word_pos(w);
317	        segs.seq(seg, pos).load(Ordering::SeqCst) == pos
318	            || (M::MULTI && !segs.in_use().load(Ordering::SeqCst) & segs.all() != 0)
319	    }
320	
321	    /// Move the ring from the full segment and position `w` names
322	    /// to a free segment.
323	    ///
324	    /// - Take the lowest free segment by setting its bit in the
325	    ///   in-use word, which serializes producers switching at
326	    ///   once and succeeds only where the bit was clear, clear its
327	    ///   seal, and CAS the claim word from `w` to the new segment
328	    ///   at its resume position, the position its seal held.
329	    /// - On success, seal the old segment: MOVED, the new segment,
330	    ///   and `w`'s position as the end. Every claim in the old
331	    ///   segment lies before it.
332	    /// - On a lost claim CAS, restore the seal and clear the bit:
333	    ///   the ring moved under the attempt, and the caller retries
334	    ///   with the fresh word.
335	    /// - Out of line and cold: inlined into the send loop it made a
336	    ///   ring that never switches run up to three times slower than
337	    ///   `Single` (design note, MPSC v3 measured), a path taken only
338	    ///   on a full ring costing every message.
339	    #[cold]
340	    #[inline(never)]
341	    fn switch(&self, w: u32) -> Result<(), NoSwitch> {
342	        let segs = &self.segs;
343	        let in_use = segs.in_use();
344	        loop {
345	            // Acquire: a consumer's give-back is visible with its
346	            // released seqs.
347	            let free = !in_use.load(Ordering::Acquire) & segs.all();
348	            if free == 0 {
349	                return Err(NoSwitch::NoFree);
350	            }
351	            let k = free.trailing_zeros();
352	            if in_use.fetch_or(1 << k, Ordering::AcqRel) & (1 << k) != 0 {
353	                // Another producer set it first.
354	                continue;
355	            }
356	            // Segment k is ours among producers, and the consumer
357	            // cannot enter it until a seal names it, so nobody else
358	            // reads or writes its seal here.
359	            let seal = segs.seal(k);
360	            let start = word_pos(seal.load(Ordering::Acquire));
361	            // Cleared before the claim CAS: a clear after it could
362	            // land after a later producer's seal of k, once the ring
363	            // has filled k and left it again, and wipe that seal.
364	            seal.store(0, Ordering::Relaxed);
365	            match segs.claim().compare_exchange(
366	                w,
367	                word(k, start) | (w & WAITING),
368	                Ordering::SeqCst,
369	                Ordering::SeqCst,
370	            ) {
371	                Ok(_) => {
372	                    // Release pairs with the consumer's Acquire seal
373	                    // load: seeing MOVED means k's seal is clear.
374	                    segs.seal(word_seg(w))
375	                        .store(MOVED | word(k, word_pos(w)), Ordering::Release);
376	                    segs.switches().fetch_add(1, Ordering::Relaxed);
377	                    return Ok(());
378	                }
379	                Err(_) => {
380	                    // Put k back as it was: its resume position for
381	                    // the next taker, then its bit.
382	                    seal.store(start, Ordering::Relaxed);
383	                    in_use.fetch_and(!(1 << k), Ordering::AcqRel);
384	                    return Err(NoSwitch::Lost);
385	                }
386	            }
387	        }
388	    }
389	}

